```c
// Print the rxdataF variable
for (int i = 0; i < ru->nb_rx; i++) {
    printf("rxdataF[%d]:\n", i);
    for (int j = 0; j < NUMBER_RX_BUFFERS * fp->symbols_per_slot * fp->ofdm_symbol_size; j++) {
