```javascript
function matrixMultiply(a, b, p) {
    let result = [[0, 0], [0, 0]];
    for (let i = 0; i < 2; i++) {
        for (let j = 0; j < 2; j++) {
            for (let k = 0; k < 2; k++) {
                result[i][j] += a[i][k] * b[k][j];
                result[i][j] %= p;
            }
        }
    }
    return result;
}

function matrixPower(matrix, n, p) {
    if (n === 1) {
        return matrix;
    }
    if (n % 2 === 0) {
        let halfPow = matrixPower(matrix, Math.floor(n / 2), p);
        return matrixMultiply(halfPow, halfPow, p);
    } else {
        let halfPow = matrixPower(matrix, Math.floor(n / 2), p);
        return matrixMultiply(matrixMultiply(halfPow, halfPow, p), matrix, p);
    }
}

function fibonacci(n, p) {
    if (n <= 1) {
        return n;
    }
    let baseMatrix = [[1, 1], [1, 0]];
    let resultMatrix = matrixPower(baseMatrix, n - 1, p);
    return resultMatrix[0][0];
}

