Below is a simplified implementation of the data storage oriented blockchain in Python:

```python
import hashlib
import time
from typing import Dict, List

class Block:
    def __init__(self, index: int, previous_hash: str, timestamp: float, data: Dict[str, str], node_id: str):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.node_id = node_id
        self.hash = self.calculate_hash()

    def calculate_hash(self) -> str:
        data_string = str(self.index) + self.previous_hash + str(self.timestamp) + str(self.data) + self.node_id
        return hashlib.sha256(data_string.encode()).hexdigest()


class Node:
    def __init__(self, node_id: str, balance: float):
        self.node_id = node_id
        self.balance = balance
        self.stored_data: Dict[str, Dict[str, str]] = {}

    def add_data(self, data_id: str, data: str, size: int, lifetime: int, blockchain: 'Blockchain'):
        deposit = blockchain.calculate_deposit(size, lifetime)
        if self.balance >= deposit:
            self.balance -= deposit
            blockchain.add_data(data_id, data, size, lifetime, self.node_id)
            self.stored_data[data_id] = {'data': data, 'size': size, 'lifetime': lifetime, 'deposit': deposit}
        else:
            print("Insufficient balance")

    def access_data(self, data_id: str, blockchain: 'Blockchain'):
        if data_id in blockchain.data:
            fee = blockchain.calculate_access_fee(data_id)
            self.balance += fee
            blockchain.data[data_id]['access_count'] += 1
            print(f"Accessed data {data_id} and earned {fee} coins")
        else:
            print("Data not found")

    def delete_data(self, data_id: str, blockchain: 'Blockchain'):
        if data_id in self.stored_data:
            blockchain.delete_data(data_id)
            self.balance += self.stored_data[data_id]['deposit']
            del self.stored_data[data_id]
            print(f"Deleted data {data_id} and got {self.stored_data[data_id]['deposit']} coins back")
        else:
            print("Data not found")


class Blockchain:
    def __init__(self):
        self.chain: List[Block] = [self.create_genesis_block()]
        self.data: Dict[str, Dict[str, str]] = {}
        self.nodes: Dict[str, Node] = {}

    def create_genesis_block(self) -> Block:
        return Block(0, "0", time.time(), {}, "Genesis")

    def get_latest_block(self) -> Block:
        return self.chain[-1]

    def add_block(self, new_block: Block):
        new_block.previous_hash = self.get_latest_block().hash
        new_block.hash = new_block.calculate_hash()
        self.chain.append(new_block)

    def add_data(self, data_id: str, data: str, size: int, lifetime: int, node_id: str):
        self.data[data_id] = {'data': data, 'size': size, 'lifetime': lifetime, 'access_count': 0, 'deposit': self.calculate_deposit(size, lifetime)}
        self.add_block(Block(len(self.chain), self.get_latest_block().hash, time.time(), {data_id: data}, node_id))

    def delete_data(self, data_id: str):
        if data_id in self.data:
            del self.data[data_id]
            self.add_block(Block(len(self.chain), self.get_latest_block().hash, time.time(), {data_id: None}, "Delete"))

    def calculate_deposit(self, size: int, lifetime: int) -> float:
        return size * lifetime * 0.01

    def calculate_access_fee(self, data_id: str) -> float:
        return self.data[data_id]['deposit'] / 100

    def reward_nodes(self):
        for data_id, data in self.data.items():
            if data['lifetime'] > 0:
                data['lifetime'] -= 1
                reward = data['deposit'] / len(self.nodes)
                for node in self.nodes.values():
                    node.balance += reward
                print(f"Rewarded nodes for storing data {data_id}")
            else:
                print(f"Data {data_id} lifetime expired")


# Example usage
blockchain = Blockchain()
node1 = Node("Node1", 1000)
node2 = Node("Node2", 1000)
blockchain.nodes["Node1"] = node1
blockchain.nodes["Node2"] = node2

node1.add_data("Data1", "Hello World", 10, 10, blockchain)
node2.add_data("Data2", "Hello Blockchain", 20, 20, blockchain)

node1.access_data("Data1", blockchain)
node2.access_data("Data2", blockchain)

blockchain.reward_nodes()

node1.delete_data("Data1", blockchain)
```

This implementation includes the following features:

*   A `Block` class to represent each block in the blockchain, containing an index, previous hash, timestamp, data, and node ID.
*   A `Node` class to represent each node in the network, containing a node ID, balance, and stored data.
*   A `Blockchain` class to manage the blockchain, including adding blocks, adding data, deleting data, calculating deposits, and rewarding nodes.
*   The `add_data` method in the `Node` class allows a node to add data to the blockchain, paying a deposit based on the data size and lifetime.
*   The `access_data` method in the `Node` class allows a node to access data stored by another node, earning a fee.
*   The `delete_data` method in the `Node` class allows a node to delete its data from the blockchain, retrieving its unused deposit.
*   The `reward_nodes` method in the `Blockchain` class rewards nodes for storing data, distributing the deposit evenly among them.

Note that this is a simplified example and may not cover all the complexities of a real-world blockchain implementation.

**Flask App with Users Boilerplate Code**
======================================

This code provides a basic structure for a Flask app with user authentication using Flask-SQLAlchemy and Flask-Login.

**Requirements**
---------------

*   Flask
*   Flask-SQLAlchemy
*   Flask-Login
*   Flask-WTF
*   Werkzeug

**Installation**
------------

You can install the required packages using pip:

```bash
pip install flask flask-sqlalchemy flask-login flask-wtf werkzeug
```

**Code**
-----

### app.py

```python
from flask import Flask, render_template, redirect, url_for
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required, current_user
from flask_wtf import FlaskForm
from wtforms import StringField, PasswordField, SubmitField
from wtforms.validators import InputRequired, Email, Length, EqualTo
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret_key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///database.db'
db = SQLAlchemy(app)

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)

    def __init__(self, **kwargs):
        super(User, self).__init__(**kwargs)
        self.password = generate_password_hash(self.password)

    def check_password(self, password):
        return check_password_hash(self.password, password)

class LoginForm(FlaskForm):
    username = StringField('Username', validators=[InputRequired(), Length(min=4, max=80)])
    password = PasswordField('Password', validators=[InputRequired(), Length(min=8, max=80)])
    submit = SubmitField('Login')

class RegisterForm(FlaskForm):
    username = StringField('Username', validators=[InputRequired(), Length(min=4, max=80)])
    email = StringField('Email', validators=[InputRequired(), Email(), Length(max=120)])
    password = PasswordField('Password', validators=[InputRequired(), Length(min=8, max=80)])
    confirm_password = PasswordField('Confirm Password', validators=[InputRequired(), EqualTo('password')])
    submit = SubmitField('Register')

login_manager = LoginManager()
login_manager.init_app(app)
login_manager.login_view = 'login'

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/login', methods=['GET', 'POST'])
def login():
    form = LoginForm()
    if form.validate_on_submit():
        user = User.query.filter_by(username=form.username.data).first()
        if user and user.check_password(form.password.data):
            login_user(user)
            return redirect(url_for('dashboard'))
    return render_template('login.html', form=form)

@app.route('/register', methods=['GET', 'POST'])
def register():
    form = RegisterForm()
    if form.validate_on_submit():
        new_user = User(username=form.username.data, email=form.email.data, password=form.password.data)
        db.session.add(new_user)
        db.session.commit()
        return redirect(url_for('login'))
    return render_template('register.html', form=form)

@app.route('/dashboard')
@login_required
def dashboard():
    return render_template('dashboard.html')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(debug=True)
```

