**Extracting Text from a Document using JavaScript**

To extract text from a document using JavaScript, you can use the following approaches:

### Approach 1: Using the `DOMParser` API

This approach is useful when you have the HTML content of the document as a string.

```javascript
/**
 * Extracts text from an HTML string.
 * @param {string} html - The HTML content of the document.
 * @returns {string} The extracted text.
 */
function extractTextFromHtml(html) {
  const parser = new DOMParser();
  const doc = parser.parseFromString(html, 'text/html');
  return doc.body.textContent;
}

// Example usage:
const html = '<html><body>Hello, <span>world!</span></body></html>';
const extractedText = extractTextFromHtml(html);
console.log(extractedText); // Output: "Hello, world!"
```

### Approach 2: Using the `FileReader` API

This approach is useful when you have a file input element and want to extract text from the selected file.

```javascript
/**
 * Extracts text from a file.
 * @param {File} file - The file to extract text from.
 * @returns {Promise<string>} A promise that resolves with the extracted text.
 */
function extractTextFromFile(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target.result;
      resolve(text);
    };
    reader.onerror = (error) => {
      reject(error);
    };
    reader.readAsText(file);
  });
}

// Example usage:
const fileInput = document.getElementById('file-input');
fileInput.addEventListener('change', (event) => {
  const file = event.target.files[0];
  extractTextFromFile(file).then((extractedText) => {
    console.log(extractedText);
  }).catch((error) => {
    console.error(error);
  });
});
```

### Approach 3: Using a Library like `pdfjs`

This approach is useful when you need to extract text from a PDF document.

```javascript
/**
 * Extracts text from a PDF file.
 * @param {File} file - The PDF file to extract text from.
 * @returns {Promise<string>} A promise that resolves with the extracted text.
 */
function extractTextFromPdf(file) {
  return new Promise((resolve, reject) => {
    const pdfjsLib = require('pdfjs-dist');
    const pdfjsWorker = require('pdfjs-dist/build/pdf.worker.entry');
    const pdfDocument = pdfjsLib.getDocument(file);
    pdfDocument.promise.then((pdf) => {
      const pages = pdf.numPages;
      const textPromises = [];
      for (let i = 1; i <= pages; i++) {
        textPromises.push(pdf.getPage(i).then((page) => {
          return page.getTextContent();
        }).then((textContent) => {
          return textContent.items.map((item) => item.str).join('');
        }));
      }
      Promise.all(textPromises).then((texts) => {
        const extractedText = texts.join('\n');
        resolve(extractedText);
      });
    }).catch((error) => {
      reject(error);
    });
  });
}

// Example usage:
