Creating a smart contract for an ERC-1155 token with a credits (CREDS) token system involves several steps. Below is a basic example of how you might structure such a contract using Solidity, the programming language used for Ethereum smart contracts. This example will include the basic functionality for creating and managing an ERC-1155 token and integrating it with a credits system.

Please note, this is a simplified example intended for educational purposes. Real-world applications may require more complex logic, security considerations, and testing.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.7.3/contracts/token/ERC1155/ERC1155.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.7.3/contracts/access/Ownable.sol";
import "https://github.com/OpenZeppelin/openzeppelin-contracts/blob/v4.7.3/contracts/utils/Context.sol";

contract CredsToken is ERC1155, Ownable {
    // Mapping from owner to list of owned token IDs
    mapping(address => mapping(uint256 => uint256)) private _balances;

    // Mapping from token ID to total supply
    mapping(uint256 => uint256) private _totalSupplies;

    // Token ID for the credits token
    uint256 public constant CREDS_TOKEN_ID = 0;

    // Event emitted when credits are minted
    event CreditsMinted(address indexed to, uint256 amount);

    // Event emitted when credits are burned
    event CreditsBurned(address indexed from, uint256 amount);

    constructor() ERC1155("https://example.com/token/{id}.json") {}

    // Function to mint new credits tokens
    function mintCredits(address to, uint256 amount) public onlyOwner {
        _mint(to, CREDS_TOKEN_ID, amount, "");
        emit CreditsMinted(to, amount);
    }

    // Function to burn credits tokens
    function burnCredits(uint256 amount) public {
        require(balanceOf(msg.sender, CREDS_TOKEN_ID) >= amount, "Not enough credits to burn");
        _burn(msg.sender, CREDS_TOKEN_ID, amount);
        emit CreditsBurned(msg.sender, amount);
    }

    // Function to check the balance of a specific token ID for an address
    function balanceOf(address account, uint256 id) public view returns (uint256) {
        return _balances[account][id];
    }

    // Function to get the total supply of a specific token ID
    function totalSupply(uint256 id) public view returns (uint256) {
        return _totalSupplies[id];
    }

    // Internal function to mint tokens
    function _mint(address to, uint256 id, uint256 amount, bytes memory data) internal {
        require(id != 0, "Cannot mint zero ID");
        _balances[to][id] += amount;
        _totalSupplies[id] += amount;
        emit TransferSingle(msg.sender, address(0), to, id, amount);
        emit URI(id, data);
    }

    // Internal function to burn tokens
    function _burn(address from, uint256 id, uint256 amount) internal {
        require(id != 0, "Cannot burn zero ID");
        _balances[from][id] -= amount;
        _totalSupplies[id] -= amount;
        emit TransferSingle(msg.sender, from, address(0), id, amount);
    }
}
```

### Important Considerations:

1. **Security Audits:** Before deploying any contract to the mainnet, it's crucial to perform thorough security audits and testing.
2. **OpenZeppelin:** This example uses OpenZeppelin's ERC1155 contract for the base functionality. Ensure you're using the latest version and understand the implications of any changes.
3. **URI Functionality:** The `_mint` function includes emitting a `URI` event. For ERC1155 tokens, the URI points to a JSON file that describes the token's metadata. You'll need to ensure this URL is correctly formatted and points to a valid JSON file.
4. **Access Control:** The `onlyOwner` modifier restricts certain functions (like `mintCredits`) to the contract owner. Consider whether this access control meets your requirements or if you need a more complex permission system.
5. **Reentrancy Attacks:** Although not directly applicable due to the nature of this contract, always be mindful of reentrancy attacks when dealing with external calls.

