```javascript
// server.js
const express = require('express');
const { Pool } = require('pg');
const bodyParser = require('body-parser');
const cors = require('cors');

const app = express();
app.use(bodyParser.json());
app.use(cors());

const pool = new Pool({
  user: 'your_username',
  host: 'your_host',
  database: 'your_database',
  password: 'your_password',
  port: 5432,
});

// Create table
app.get('/create-table', async (req, res) => {
  const query = `
    CREATE TABLE IF NOT EXISTS todos (
      id SERIAL PRIMARY KEY,
      title VARCHAR(255) NOT NULL,
      completed BOOLEAN NOT NULL DEFAULT FALSE
    );
  `;
  try {
    await pool.query(query);
    res.status(201).send('Table created');
  } catch (err) {
    console.error(err);
    res.status(500).send('Error creating table');
  }
});

// Get all todos
app.get('/todos', async (req, res) => {
  const query = 'SELECT * FROM todos';
  try {
    const result = await pool.query(query);
    res.json(result.rows);
  } catch (err) {
    console.error(err);
    res.status(500).send('Error getting todos');
  }
});

// Create new todo
app.post('/todos', async (req, res) => {
  const { title } = req.body;
  const query = {
    text: 'INSERT INTO todos (title) VALUES ($1) RETURNING *',
    values: [title],
  };
  try {
    const result = await pool.query(query);
    res.json(result.rows[0]);
  } catch (err) {
    console.error(err);
    res.status(500).send('Error creating todo');
  }
});

// Update todo
app.put('/todos/:id', async (req, res) => {
  const { id } = req.params;
  const { title, completed } = req.body;
  const query = {
    text: 'UPDATE todos SET title = $1, completed = $2 WHERE id = $3 RETURNING *',
    values: [title, completed, id],
  };
  try {
    const result = await pool.query(query);
    res.json(result.rows[0]);
  } catch (err) {
    console.error(err);
    res.status(500).send('Error updating todo');
  }
});

// Delete todo
app.delete('/todos/:id', async (req, res) => {
  const { id } = req.params;
  const query = {
    text: 'DELETE FROM todos WHERE id = $1',
    values: [id],
  };
