**Prime Number Stream Generator in Rust**
====================================================

Below is an example implementation of a prime number stream generator in Rust. This generator uses a trial division method to check for primality.

```rust
/// Prime number stream generator
pub struct PrimeStream {
    current: u64,
}

impl PrimeStream {
    /// Create a new prime number stream generator
    pub fn new() -> Self {
        PrimeStream { current: 1 }
    }
}

impl Iterator for PrimeStream {
    type Item = u64;

    /// Get the next prime number in the stream
    fn next(&mut self) -> Option<Self::Item> {
        loop {
            self.current += 1;
            if is_prime(self.current) {
                return Some(self.current);
            }
        }
    }
}

/// Check if a number is prime
fn is_prime(n: u64) -> bool {
    if n <= 1 {
        return false;
    }
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    let mut i = 3;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 2;
    }
    true
}

fn main() {
    let mut prime_stream = PrimeStream::new();
    for _ in 0..10 {
        println!("{}", prime_stream.next().unwrap());
    }
}
```

