**Simple RNN Implementation in TypeScript**
======================================

This implementation provides a basic Recurrent Neural Network (RNN) using plain TypeScript. It includes methods for forward pass, backward pass, and weight updates.

**RNN Model**
-------------

```typescript
interface RNNOptions {
  inputSize: number;
  hiddenSize: number;
  outputSize: number;
}

class RNN {
  private inputSize: number;
  private hiddenSize: number;
  private outputSize: number;
  private weights: { [key: string]: number[][] };
  private biases: { [key: string]: number[] };

  constructor(options: RNNOptions) {
    this.inputSize = options.inputSize;
    this.hiddenSize = options.hiddenSize;
    this.outputSize = options.outputSize;

    this.weights = {
      ih: this.initializeWeights(this.inputSize, this.hiddenSize),
      hh: this.initializeWeights(this.hiddenSize, this.hiddenSize),
      ho: this.initializeWeights(this.hiddenSize, this.outputSize),
    };

    this.biases = {
      h: this.initializeBiases(this.hiddenSize),
      o: this.initializeBiases(this.outputSize),
    };
  }

  private initializeWeights(inputSize: number, outputSize: number): number[][] {
    const weights: number[][] = [];
    for (let i = 0; i < inputSize; i++) {
      weights[i] = [];
      for (let j = 0; j < outputSize; j++) {
        weights[i][j] = Math.random() * 2 - 1;
      }
    }
    return weights;
  }

  private initializeBiases(size: number): number[] {
    const biases: number[] = [];
    for (let i = 0; i < size; i++) {
      biases[i] = Math.random() * 2 - 1;
    }
    return biases;
  }

  private sigmoid(x: number): number {
    return 1 / (1 + Math.exp(-x));
  }

  private tanh(x: number): number {
    return Math.tanh(x);
  }

  private softmax(x: number[]): number[] {
    const max = Math.max(...x);
    const expX = x.map((val) => Math.exp(val - max));
    const sumExpX = expX.reduce((acc, val) => acc + val, 0);
    return expX.map((val) => val / sumExpX);
  }

  forward(input: number[], hiddenState: number[]): { output: number[]; newHiddenState: number[] } {
    const hidden = this.sigmoid(
      this.dotProduct(this.weights.ih, input) +
        this.dotProduct(this.weights.hh, hiddenState) +
        this.biases.h
    );

    const output = this.softmax(
      this.dotProduct(this.weights.ho, hidden) + this.biases.o
    );

    return { output, newHiddenState: hidden };
  }

  backward(
    input: number[],
    hiddenState: number[],
    outputError: number[],
    newHiddenState: number[]
  ): { inputError: number[]; hiddenError: number[] } {
    const outputDelta = outputError;

    const hiddenError = this.dotProduct(this.transpose(this.weights.ho), outputDelta);

    const hiddenDelta = hiddenError * this.tanhDerivative(newHiddenState);

    const inputError = this.dotProduct(this.transpose(this.weights.ih), hiddenDelta);

    return { inputError, hiddenError };
  }

  updateWeights(
    input: number[],
    hiddenState: number[],
    outputError: number[],
    newHiddenState: number[],
    learningRate: number
  ): void {
    const { inputError, hiddenError } = this.backward(input, hiddenState, outputError, newHiddenState);

    this.weights.ih = this.updateWeightMatrix(this.weights.ih, input, hiddenError, learningRate);
    this.weights.hh = this.updateWeightMatrix(this.weights.hh, hiddenState, hiddenError, learningRate);
    this.weights.ho = this.updateWeightMatrix(this.weights.ho, newHiddenState, outputError, learningRate);

    this.biases.h = this.updateBias(this.biases.h, hiddenError, learningRate);
    this.biases.o = this.updateBias(this.biases.o, outputError, learningRate);
  }

  private dotProduct(weights: number[][], input: number[]): number[] {
    const output: number[] = [];
    for (let i = 0; i < weights[0].length; i++) {
      let sum = 0;
      for (let j = 0; j < input.length; j++) {
        sum += weights[j][i] * input[j];
      }
      output.push(sum);
    }
    return output;
  }

  private transpose(matrix: number[][]): number[][] {
    const transposed: number[][] = [];
    for (let i = 0; i < matrix[0].length; i++) {
      transposed[i] = [];
      for (let j = 0; j < matrix.length; j++) {
        transposed[i][j] = matrix[j][i];
      }
    }
    return transposed;
  }

  private updateWeightMatrix(weights: number[][], input: number[], error: number[], learningRate: number): number[][] {
    for (let i = 0; i < weights.length; i++) {
      for (let j = 0; j < weights[0].length; j++) {
        weights[i][j] += learningRate * input[i] * error[j];
      }
    }
    return weights;
  }

  private updateBias(bias: number[], error: number[], learningRate: number): number[] {
    for (let i = 0; i < bias.length; i++) {
      bias[i] += learningRate * error[i];
    }
    return bias;
  }

  private tanhDerivative(x: number[]): number[] {
    return x.map((val) => 1 - val * val);
  }
}
```

**Example Use Case**
-------------------

