    }

    newSprite() {
        this.sprite = new Array(this.size).fill(0).map(() => new Array(this.size).fill(0));
        this.drawSprite();
    }

    saveSprite() {
        const spriteName = document.getElementById('sprite-name').value;
        const spriteData = this.sprite.map((row) => row.join('')).join('');
        const spriteJSON = JSON.stringify({ name: spriteName, data: spriteData, size: this.size });
        console.log(spriteJSON);
    }

    startDraw(e) {
        const rect = this.canvas.getBoundingClientRect();
        const x = Math.floor((e.clientX - rect.left) / (this.canvas.width / this.size));
        const y = Math.floor((e.clientY - rect.top) / (this.canvas.height / this.size));
        this.drawPixel(x, y);
    }

    draw(e) {
        if (e.buttons === 1) {
            const rect = this.canvas.getBoundingClientRect();
            const x = Math.floor((e.clientX - rect.left) / (this.canvas.width / this.size));
            const y = Math.floor((e.clientY - rect.top) / (this.canvas.height / this.size));
            this.drawPixel(x, y);
        }
    }

    stopDraw() {}

    drawPixel(x, y) {
        if (this.sprite && x >= 0 && x < this.size && y >= 0 && y < this.size) {
            this.sprite[y][x] = 1;
            this.drawSprite();
        }
    }

    drawSprite() {
        this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
        if (this.sprite) {
            for (let y = 0; y < this.size; y++) {
                for (let x = 0; x < this.size; x++) {
                    if (this.sprite[y][x] === 1) {
                        this.ctx.fillStyle = this.color;
                        this.ctx.fillRect(x * (this.canvas.width / this.size), y * (this.canvas.height / this.size), this.canvas.width / this.size, this.canvas.height / this.size);
                    }
                }
            }
        }
    }
}

