export const useSessionStore = defineStore('session', {
  state: () => ({
    // Initialize state properties here
    username: '',
    email: '',
  }),
});
```

Then, in your component, you can use the `useSessionQuery` hook to fetch the session data and update the Pinia store with the selected keys.

```javascript
// MyComponent.vue
<template>
  <!-- Your component template here -->
</template>

<script>
import { useSessionQuery } from './useSessionQuery';
import { useSessionStore } from './stores/sessionStore';

export default {
  setup() {
    const sessionStore = useSessionStore();
    const { data, isLoading, isError } = useSessionQuery();

    // Watch for changes in the data and update the store
    watch(data, (newData) => {
