### Recursive JSON Search Function
#### Overview
The following JavaScript function recursively searches a JSON object for a specified entity key, returning the key's value and location.

#### Code
```javascript
/**
 * Recursively searches a JSON object for a specified entity key.
 * 
 * @param {Object} json - The JSON object to search.
 * @param {string} key - The entity key to search for.
 * @returns {Array} An array containing the key's value and location.
 */
function recursiveJsonSearch(json, key) {
    // Initialize the result array
    let result = [];

    // Define a recursive search function
    function search(obj, currentPath) {
        // Iterate over the object's properties
        for (let prop in obj) {
            // Construct the current property path
            let path = currentPath ? `${currentPath}.${prop}` : prop;

            // Check if the property matches the search key
            if (prop === key) {
                // Add the key's value and location to the result array
                result.push([obj[prop], path]);
            }

            // Recursively search nested objects
            if (typeof obj[prop] === 'object') {
                search(obj[prop], path);
            }
        }
    }

    // Start the recursive search
    search(json, '');

    // Return the result array
    return result;
}

// Example usage
let json = {
    "id": 1,
    "name": "John Doe",
    "address": {
        "street": "123 Main St",
        "city": "Anytown",
        "state": "CA",
        "zip": "12345"
    },
    "phone": {
        "home": "555-1234",
        "work": "555-5678"
    }
};

let key = "city";
let result = recursiveJsonSearch(json, key);
console.log(result); // Output: [["Anytown", "address.city"]]
```

#### Explanation

1. The `recursiveJsonSearch` function takes a JSON object and an entity key as input.
2. It initializes an empty result array to store the key's value and location.
3. The function defines a recursive `search` function to traverse the JSON object.
4. The `search` function iterates over the object's properties and checks if each property matches the search key.
5. If a match is found, the key's value and location are added to the result array.
6. The function recursively searches nested objects by calling itself with the nested object and the current property path.
7. Finally, the `recursiveJsonSearch` function returns the result array containing the key's value and location.

#### Example Use Case

In the example usage, we define a JSON object with nested properties. We then call the `recursiveJsonSearch` function with the key "city" and log the result to the console. The output is an array containing the value "Anytown" and the location "address.city", indicating that the key "city" was found in the "address" object.

