To get the deep down nested SVG object bounding box using JavaScript, you can use the `getBBox()` method. However, this method only returns the bounding box for the element itself, not its children. 

For nested SVG objects, you can recursively traverse the SVG elements and calculate the bounding box for each child element. Then, you can use the `getScreenCTM()` method to convert the local coordinates to global coordinates.

Here's a simplified example:

```javascript
function getNestedBBox(svgElement) {
  let xMin = Infinity;
  let yMin = Infinity;
  let xMax = -Infinity;
  let yMax = -Infinity;

  function traverse(element) {
    const bbox = element.getBBox();
    const ctm = element.getScreenCTM();
    if (ctm) {
      const x = ctm.e + bbox.x * ctm.a;
      const y = ctm.f + bbox.y * ctm.d;
      const width = bbox.width * ctm.a;
      const height = bbox.height * ctm.d;

      xMin = Math.min(xMin, x);
      yMin = Math.min(yMin, y);
      xMax = Math.max(xMax, x + width);
      yMax = Math.max(yMax, y + height);
    }

    for (const child of element.children) {
      traverse(child);
    }
  }

  traverse(svgElement);

  return { x: xMin, y: yMin, width: xMax - xMin, height: yMax - yMin };
}
```

This function will return the bounding box for the given SVG element and all its children. Note that this is a simplified example and might need adjustments based on your specific SVG structure and requirements.
